"""Generate maximum-scale requests for timing."""
import json, random, sys

def addr_text(value):
    return ':'.join('%x' % ((value >> (16*(7-i))) & 0xffff) for i in range(8))

def make_case(runs_list, cap=12, seed=0, nbursts=64, naddr=64, extra=0, erase_all=True):
    rng = random.Random(seed)
    initial = [["::/0", 0]]
    R0 = runs_list[0]
    for i in range(R0-1):
        initial.append([addr_text(i+1)+"/128", i+1])
    for i in range(extra):
        # redundant routes fully covered by ::/0 with the same hop: no new runs
        initial.append([addr_text((i+1) << 70)+"/120", 0])
    txs = []
    for v in range(1, len(runs_list)):
        tx = []
        if erase_all and runs_list[v] == 1 and R0 > 1:
            for i in range(R0-1):
                tx.append(["erase", addr_text(i+1)+"/128"])
            R0 = 1
        txs.append(tx)
    bursts = []
    for b in range(nbursts):
        v = rng.randrange(len(runs_list))
        addrs = [addr_text(rng.randrange(0, 1<<128)) for _ in range(naddr)]
        bursts.append({"version": v, "repeat": rng.randrange(1, 1000001), "addresses": addrs})
    hit = rng.randrange(1,17); miss = rng.randrange(hit,257)
    return {"initial": initial, "transactions": txs, "bursts": bursts,
            "cache_pages": cap, "costs": {"hit": hit, "miss": miss,
            "decode": [rng.randrange(0,17) for _ in range(3)]}}

if __name__ == "__main__":
    kind = sys.argv[1] if len(sys.argv)>1 else "big"
    if kind == "big":
        c1 = make_case([64]+[1]*7, nbursts=64, naddr=64, seed=1)
        c2 = make_case([34]+[1]*7, nbursts=60, naddr=64, seed=2)
        c3 = make_case([1]*8, nbursts=4, naddr=64, seed=3)
        c4 = make_case([1]*8, nbursts=0, naddr=0, seed=4)
        req = {"cases":[c1,c2,c3,c4]}
    elif kind == "wide":
        req = {"cases":[make_case([4]*8, nbursts=16, naddr=32, seed=i) for i in range(4)]}
    elif kind == "routes":
        # 30000 active routes collapsing to 64 runs; two committed versions
        c = make_case([64,64], nbursts=64, naddr=64, seed=5, extra=29936, erase_all=False)
        req = {"cases":[c]}
    elif kind == "rows":
        # 60000 initial rows plus changes, one big erase transaction
        c = make_case([64]+[1]*7, nbursts=64, naddr=64, seed=6, extra=0)
        big = []
        for i in range(59000):
            big.append(["set", addr_text((i+1) << 60)+"/120", 0])
        c["transactions"][1] = big
        req = {"cases":[c]}
    elif kind == "single":
        req = {"cases":[make_case([64]+[1]*7, nbursts=64, naddr=64, seed=7)]}
    print(json.dumps(req))
PYEOF
